public class RepeatKeys {
    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(new File("dup.txt"));
        sc.nextLine();
        Map<String, Integer> seen = new HashMap<>();
        int rows = 0;
        while (sc.hasNextLine()) {
            String id = sc.nextLine().split(",")[0];
            seen.merge(id, 1, Integer::sum);
            rows++;
        }
        sc.close();
        int keys = 0;
        int involved = 0;
        for (int c : seen.values()) {
            if (c > 1) { keys++; involved += c; }
        }
